            fillColor: { index: -1, valIndex: -1, value: null },
            strokeColor: { index: -1, valIndex: -1, value: null },
            strokeWidth: { index: -1, valIndex: -1, value: null },
            blink: { index: -1, valIndex: -1, value: null }
