            const { getTextDimensions } = shmi.requires("visuals.controls.iqtrend.common");
            const markerDims = getTextDimensions("123", this.fontStyle);
            this.markerHeight = markerDims.textHeight;

            this.min = min;
            this.max = max;
            this.numSteps = numSteps;
